// Custom plans stay in this browser; the canonical catalogue is read-only.
const WB_KEYS=Object.keys(statNames),WB_STORE='fw-custom-training-v1';
let wbDraft=null,wbSaves=[],wbComparison=null,wbExpanded=false,wbProjects={},wbCharacter='c7',wbApplied={};
try{const data=JSON.parse(localStorage.getItem(WB_STORE)||'{}');wbSaves=Array.isArray(data.saves)?data.saves.filter(s=>s&&typeof s==='object'&&typeof s.name==='string').slice(0,30):[];wbProjects=data.projects&&typeof data.projects==='object'&&!Array.isArray(data.projects)?data.projects:{};wbCharacter=typeof data.characterId==='string'?data.characterId:(data.draft?.characterId||'c7');if(data.draft)wbDraft=data.draft;wbApplied=data.applied&&typeof data.applied==='object'?data.applied:{};}catch{}
function wbClass(id){return DB.classes.find(c=>c.id===id||c.cn===id||c.title===id);}
function wbThirdOnlyClass(cl,c){if(cl.cn==='舞者')return c?.id!=='c7';return /最上级|神将/.test(cl.col_1)||/第三部|第3部|救世篇/.test(cl.unlock||'');}
function wbNumber(v,min=0,max=999){const n=Number(v);return Number.isFinite(n)?Math.min(max,Math.max(min,n)):min;}
function wbAvailable(id){const c=DB.characters.find(c=>c.id===id);if(!c)return [];const rs=Object.keys(CATALOG.planning[id].routes).filter(r=>c.joinDetails.some(j=>j.route===r+'編'&&j.method!=='対象外'));return rs.length?rs:['common'];}
function wbRouteName(r){return r==='common'?'共通／后期':routes[r]+'篇';}
function wbPreset(id,r){const c=DB.characters.find(c=>c.id===id)||DB.characters[0],p=CATALOG.planning[c.id],build=p.routes[r]?.build||p.summary,level=Number(c.baseLevel)||(c.firstPart?1:45);if(c.canChangeClass===false)return wbValidate({version:1,characterId:c.id,name:c.cn+'自定义方案',level,baselineKnown:!!c.baseStats,base:c.baseStats||{},growth:c.growth,stages:[{classId:wbClass(c.startClass).id,levels:Math.max(0,60-level),phase:'third',multiplier:1,reason:'固定职业角色，仅估算出战升级成长；不安排转职或斗技场训练。'}],notes:''});const names=[wbClass(c.startClass)?.cn||'平民',(p.routes[r]?.initial||p.initial).name,build.mid[0],build.upper[0],build.end.split(' / ')[0]],ends=[5,20,35,45,60];let start=level,stages=[];for(let i=0;i<names.length;i++){const end=Math.max(start,ends[i]);if(end>start)stages.push({classId:wbClass(names[i]).id,levels:end-start,pet:'',friendship:0,multiplier:1,reason:''});start=end;}if(!stages.length)stages=[{classId:wbClass(names.at(-1)).id,levels:0,pet:'',friendship:0,multiplier:1,reason:''}];return wbValidate({version:1,characterId:c.id,name:c.cn+'自定义方案',level,baselineKnown:!!c.baseStats,base:Object.fromEntries(WB_KEYS.map(k=>[k,Number(c.baseStats?.[k])||0])),growth:Object.fromEntries(WB_KEYS.map(k=>[k,Number(c.growth[k])||0])),stages,notes:''});}
function wbValidate(d){if(!d||typeof d!=='object'||!DB.characters.some(c=>c.id===d.characterId))throw Error('方案中的角色无效');if(!Array.isArray(d.stages)||!d.stages.length||d.stages.length>8)throw Error('方案需包含1–8个阶段');const character=DB.characters.find(c=>c.id===d.characterId),out={version:1,baselineKnown:typeof d.baselineKnown==='boolean'?d.baselineKnown:!!character.baseStats,characterId:d.characterId,name:String(d.name||'自定义方案').slice(0,60),level:Math.floor(wbNumber(d.level,1,99)),base:{},growth:{},notes:String(d.notes||'').slice(0,3000),stages:[]};for(const k of WB_KEYS){out.base[k]=wbNumber(d.base?.[k]);out.growth[k]=wbNumber(d.growth?.[k],0,300);}let total=out.level,third=character.firstPart===false;for(const s of d.stages){const cl=wbClass(s.classId);if(!cl)throw Error('方案中的职业无效');const n=Math.floor(wbNumber(s.levels,0,99-total));total+=n;third=third||s.phase==='third'||wbThirdOnlyClass(cl,character);out.stages.push({classId:cl.id,phase:third?'third':'early',levels:n,pet:CATALOG.petGuide.pets.some(p=>p.id===s.pet)?s.pet:'',friendship:Math.floor(wbNumber(s.friendship,0,5)),multiplier:wbNumber(s.multiplier,0,2),reason:String(s.reason||'').slice(0,1500)});}return out;}
function wbState(){if(!wbDraft)wbDraft=wbPreset('c7');try{wbDraft=wbValidate(wbDraft);}catch{wbDraft=wbPreset('c7');}return wbDraft;}
function wbSplitPlan(input){const d=wbValidate(input);return {d,early:d.stages.filter(s=>s.phase==='early'),third:d.stages.filter(s=>s.phase==='third')};}
function wbCalculate(input,{untilThird=false}={}){const d=wbValidate(input),character=DB.characters.find(c=>c.id===d.characterId),stats={...d.base},rows=[],warnings=[];let level=d.level;if(!d.baselineKnown)warnings.push('起始面板尚未确认，当前只展示成长增量，不计入绝对属性融合。');for(const [i,s]of d.stages.entries()){if(untilThird&&s.phase==='third')break;const cl=wbClass(s.classId),pet=CATALOG.petGuide.pets.find(p=>p.id===s.pet),compatible=pet?.compatibleClasses.includes(cl.cn)&&character.canRide!==false;if(character.canRide===false&&cl.allowedSkills.some(s=>['马术','飞行术'].includes(s)))warnings.push('阶段'+(i+1)+'：'+character.cn+'不能骑乘，此职业仅作数值假设。');if(cl.col_2?.includes('女性')&&character.gender!=='女'||cl.col_2?.includes('男性')&&character.gender!=='男')warnings.push('阶段'+(i+1)+'：不满足职业性别条件。');if(cl.unlock)warnings.push('阶段'+(i+1)+'：'+cl.unlock);if(pet&&!compatible)warnings.push('阶段'+(i+1)+'：'+pet.name+'不符合本方案骑乘条件（不兼容），未计坐骑成长。');if(pet&&compatible&&s.friendship<5)warnings.push('阶段'+(i+1)+'：未到友好5，未套用满友好成长修正。');const growth=Object.fromEntries(WB_KEYS.map(k=>[k,Math.max(0,d.growth[k]+Number(cl.growth[k]||0)+(compatible&&s.friendship===5?Number(pet.growth[k]||0)*s.multiplier:0))]));for(const k of WB_KEYS)stats[k]+=s.levels*growth[k]/100;rows.push({className:cl.cn,phase:s.phase,start:level,end:level+s.levels,growth,stats:{...stats},gains:Object.fromEntries(WB_KEYS.map(k=>[k,stats[k]-d.base[k]]))});if(Number(cl.col_31)>level)warnings.push('阶段'+(i+1)+'：起点低于'+cl.cn+'资料参考等级'+cl.col_31+'，请确认实际转职资格。');level+=s.levels;}return {stats,gains:Object.fromEntries(WB_KEYS.map(k=>[k,stats[k]-d.base[k]])),baselineKnown:d.baselineKnown,rows,level,warnings};}
function wbProjectValidate(p){if(p?.version!==2||!DB.characters.some(c=>c.id===p.characterId))throw Error('多路线方案格式无效');const allowed=wbAvailable(p.characterId),lanes={};for(const [r,d]of Object.entries(p.lanes||{})){if(!allowed.includes(r))throw Error('该角色不能加入'+wbRouteName(r));if(d.characterId!==p.characterId)throw Error('不能合并不同角色');lanes[r]=wbValidate(d);}if(!Object.keys(lanes).length)throw Error('至少保留一条路线');const activeRoute=lanes[p.activeRoute]?p.activeRoute:Object.keys(lanes)[0],selected=Array.isArray(p.selected)?p.selected.filter(r=>lanes[r]):Object.keys(lanes);return {version:2,continuationRoute:lanes[p.continuationRoute]?p.continuationRoute:activeRoute,characterId:p.characterId,name:String(p.name||'多路线方案').slice(0,60),activeRoute,lanes,selected:[...new Set(selected)]};}
function wbMigrate(input){if(input?.version===2)return wbProjectValidate(input);const d=wbValidate(input),r=wbAvailable(d.characterId)[0];return wbProjectValidate({version:2,characterId:d.characterId,name:d.name,activeRoute:r,lanes:{[r]:d},selected:[r]});}
function wbProject(id=wbCharacter){if(wbDraft&&!wbProjects[wbDraft.characterId]){try{wbProjects[wbDraft.characterId]=wbMigrate(wbDraft);}catch{}}if(!DB.characters.some(c=>c.id===id))id='c7';wbCharacter=id;if(!wbProjects[id]){if(wbDraft?.characterId===id){wbProjects[id]=wbMigrate(wbDraft);}else{const available=wbAvailable(id),preferred=CATALOG.planning[id].primary?.primaryRoute,r=available.includes(preferred)?preferred:available[0];wbProjects[id]=wbMigrate(wbPreset(id,r));if(r!==wbProjects[id].activeRoute){const p=wbProjects[id];p.lanes={[r]:wbPreset(id,r)};p.activeRoute=r;p.selected=[r];}}}try{wbProjects[id]=wbProjectValidate(wbProjects[id]);}catch{wbProjects[id]=wbMigrate(wbPreset(id,wbAvailable(id)[0]));}wbDraft=wbProjects[id].lanes[wbProjects[id].activeRoute];return wbProjects[id];}
function wbFusion(p){p=wbProjectValidate(p);const results=p.selected.filter(route=>route!=='common').map(route=>({route,...wbCalculate(p.lanes[route],{untilThird:true})})),eligible=results.filter(r=>r.baselineKnown),excluded=results.filter(r=>!r.baselineKnown).map(r=>r.route),stats=eligible.length?Object.fromEntries(WB_KEYS.map(k=>[k,Math.max(...eligible.map(r=>r.stats[k]))])):null,level=eligible.length?Math.max(...eligible.map(r=>r.level)):null,route=p.continuationRoute,parts=wbSplitPlan(p.lanes[route]);let continuation=null;if(parts.third.length){const common=route==='common',base=common?parts.d.base:stats,start=common?parts.d.level:level;if(base){continuation={route,...wbCalculate({...parts.d,base,level:start,baselineKnown:common?parts.d.baselineKnown:true,stages:parts.third})};}}return {results,stats,level,excluded,continuation,continuationRoute:route};}
function wbPersist(){try{localStorage.setItem(WB_STORE,JSON.stringify({version:2,characterId:wbCharacter,projects:wbProjects,draft:wbDraft,saves:wbSaves,applied:wbApplied}));return true;}catch{return false;}}
let wbLastError='',wbUndoSnapshot=null;
function wbClassIssue(c,cl){if(c.canChangeClass===false&&cl.cn!==c.startClass)return '本角色不能转职，只能使用'+c.startClass+'。';if(c.canRide===false&&cl.allowedSkills.some(s=>['马术','飞行术'].includes(s)))return c.cn+'不能骑乘此职业。';if(cl.col_2?.includes('女性')&&c.gender!=='女'||cl.col_2?.includes('男性')&&c.gender!=='男')return '不满足职业性别条件。';return '';}
function wbPlanIssues(input){const d=wbValidate(input),c=DB.characters.find(c=>c.id===d.characterId);return d.stages.flatMap((s,i)=>{const issue=wbClassIssue(c,wbClass(s.classId));return issue?['阶段'+(i+1)+'：'+issue]:[];});}
function wbRemember(p){wbUndoSnapshot=JSON.parse(JSON.stringify(p));}
function wbSaveApply(input){const p=wbProjectValidate(input),issues=Object.entries(p.lanes).flatMap(([r,d])=>wbPlanIssues(d).map(issue=>wbRouteName(r)+' '+issue));wbLastError='';if(issues.length){wbLastError='无法应用：'+issues.join(' ');return false;}const old=wbApplied[p.characterId],saved=wbSaves;wbApplied[p.characterId]=JSON.parse(JSON.stringify(p));wbSaves=[JSON.parse(JSON.stringify(p)),...wbSaves].slice(0,30);if(wbPersist())return true;if(old)wbApplied[p.characterId]=old;else delete wbApplied[p.characterId];wbSaves=saved;return false;}
function wbOptions(selected,c){return DB.classes.filter(cl=>c?.canChangeClass!==false||cl.cn===c.startClass||cl.id===selected).map(c=>`<option value="${c.id}" ${c.id===selected?'selected':''}>${esc(c.cn)} · ${esc(c.col_1)}</option>`).join('');}

function wbCharacterChooser(c){return `<div class="wb-character-control"><span class="wb-field-label">养成角色</span><button id="wb-character-toggle" class="wb-character-toggle" data-wb-picker-toggle aria-expanded="false" aria-controls="wb-character-picker" aria-label="更换养成角色，当前${esc(c.cn)}">${portrait(c,true)}<span><b>${esc(c.cn)}</b><small data-skill-images="off">${esc(c.role)}</small></span><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="m6 9 6 6 6-6"/></svg></button><section id="wb-character-picker" class="wb-character-picker" aria-label="选择养成角色" hidden><label class="wb-picker-search">搜索角色<input type="search" data-wb-character-search placeholder="输入姓名或别名…" autocomplete="off"></label><div class="wb-picker-list">${DB.characters.map(person=>`<button data-wb-pick="${person.id}" data-wb-pick-search="${esc([person.cn,person.name,person.alias||''].join(' ').toLowerCase())}" aria-pressed="${person.id===c.id}" aria-label="选择${esc(person.cn)}">${portrait(person)}<span><b>${esc(person.cn)}</b><small data-skill-images="off">${esc(person.role)}</small></span>${person.id===c.id?'<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="m5 12 4 4L19 6"/></svg>':''}</button>`).join('')}</div><div class="wb-picker-empty" role="status" hidden>没有匹配角色，请换个姓名或别名。</div></section></div>`;}
function wbRouteAvatar(r){const hero=CATALOG.presentation.heroes.find(h=>h.route===r),c=hero&&DB.characters.find(c=>c.id===hero.id);return c?portrait(c):'';}
function wbClosePicker(focus=false){const panel=document.querySelector('#wb-character-picker'),toggle=document.querySelector('#wb-character-toggle');if(panel)panel.hidden=true;toggle?.setAttribute('aria-expanded','false');if(focus)toggle?.focus();}
document.addEventListener('click',e=>{const toggle=e.target.closest('[data-wb-picker-toggle]');if(toggle){const panel=document.querySelector('#wb-character-picker');panel.hidden=!panel.hidden;toggle.setAttribute('aria-expanded',String(!panel.hidden));if(!panel.hidden)panel.querySelector('input').focus();return;}const pick=e.target.closest('[data-wb-pick]');if(pick){wbProject(pick.dataset.wbPick);wbUpdate(true);document.querySelector('#wb-character-toggle')?.focus();return;}if(!e.target.closest('.wb-character-control'))wbClosePicker();});
document.addEventListener('input',e=>{if(!e.target.hasAttribute('data-wb-character-search'))return;const q=e.target.value.trim().toLowerCase();let count=0;document.querySelectorAll('[data-wb-pick]').forEach(b=>{b.hidden=!b.dataset.wbPickSearch.includes(q);if(!b.hidden)count++;});document.querySelector('.wb-picker-empty').hidden=count>0;});
document.addEventListener('keydown',e=>{const panel=document.querySelector('#wb-character-picker');if(panel&&!panel.hidden&&e.key==='Escape'){e.preventDefault();wbClosePicker(true);}if(e.target.hasAttribute?.('data-wb-character-search')&&e.key==='ArrowDown'){e.preventDefault();panel.querySelector('[data-wb-pick]:not([hidden])')?.focus();}});

function wbStatFields(kind,d){return WB_KEYS.map(k=>`<label><span>${statNames[k]}${kind==='growth'?' %':''}</span><input type="number" min="0" max="${kind==='growth'?300:999}" step="1" inputmode="decimal" data-wb-stat="${kind}:${k}" aria-label="${kind==='growth'?'基础成长':'起始属性'}${statNames[k]}" value="${d[k]}"></label>`).join('');}
function wbReason(c,s){return s.reason||CATALOG.planning[c.id].audit.classReasons[wbClass(s.classId).cn]?.why||'按当前职责选择；转职前核对职业资格与解锁条件。';}
function wbAlternatives(c,cl,r){const p=CATALOG.planning[c.id],b=p.routes[r]?.build||p.summary,group=[b.mid,b.upper,b.end.split(' / ')].find(ns=>ns.includes(cl.cn));return group&&group.length>1?'<div class="path-alternatives"><small>备选</small>'+group.filter(n=>n!==cl.cn).map(n=>{const other=wbClass(n);return `<button class="text-button" data-reference-type="class" data-reference-id="${other.id}">${esc(n)}</button>`}).join('')+'</div>':'';}
function wbStats(stats,compact=false){return statPanel(stats,compact?['str','mag','spd']:Object.keys(statNames),1);}
function wbGraph(c,d,{compact=false,edit=false,r='common',alternatives=false}={}){const result=wbCalculate(d);return `${!result.baselineKnown?'<p class="wb-caption">起始面板未确认，以下仅显示成长增量。</p>':''}<div class="career-graph-scroll" tabindex="0" aria-label="${esc(c.cn)}横向职业路线${compact?'，左右滑动查看':''}"><ol class="career-graph ${compact?'compact-graph':''} ${edit?'editable-graph':''}">${d.stages.map((s,i)=>{const cl=wbClass(s.classId),row=result.rows[i],pets=CATALOG.petGuide.pets.filter(p=>p.compatibleClasses.includes(cl.cn));return `<li class="career-node" ${edit?`id="wb-node-${i}"`:''}><div class="career-node-head">${classIcon(cl,36)}<div class="path-level">Lv.${row.start}<span>→ ${row.end}</span></div></div>${edit?`<label>职业<select data-wb-stage="${i}:classId" aria-label="阶段${i+1}职业">${wbOptions(s.classId,c)}</select></label><label>培养时期<select data-wb-stage="${i}:phase" aria-label="阶段${i+1}培养时期"><option value="early" ${s.phase==='early'?'selected':''} ${wbThirdOnlyClass(cl,c)||c.firstPart===false?'disabled':''}>融合前（第一、二部）</option><option value="third" ${s.phase==='third'?'selected':''}>第三部续养</option></select></label><label>结束等级<input type="number" min="${row.start}" max="99" value="${row.end}" data-wb-stage="${i}:end" aria-label="阶段${i+1}结束等级"></label>`:`<button class="path-class" data-reference-type="class" data-reference-id="${cl.id}">${esc(cl.cn)}</button>`}${wbClassIssue(c,cl)?`<p class="wb-node-issue" role="alert">${esc(wbClassIssue(c,cl))}</p>`:''}${alternatives?wbAlternatives(c,cl,r):''}<small>Lv.${row.end} ${result.baselineKnown?'永久属性期望':'成长增量'}</small><div data-wb-node-stats="${i}">${wbStats(result.baselineKnown?row.stats:row.gains,compact)}</div>${edit?`<label class="path-reason">我的选择理由<textarea rows="3" maxlength="1500" data-wb-stage="${i}:reason" placeholder="${esc(wbReason(c,{...s,reason:''}))}">${esc(s.reason)}</textarea></label>${pets.length?`<details class="wb-mounts"><summary>坐骑修正</summary><label>坐骑<select data-wb-stage="${i}:pet"><option value="">不计坐骑</option>${pets.map(p=>`<option value="${p.id}" ${s.pet===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><label>友好等级<select data-wb-stage="${i}:friendship">${[0,1,2,3,4,5].map(n=>`<option ${n===s.friendship?'selected':''}>${n}</option>`).join('')}</select></label><label>成长倍率<input type="number" min="0" max="2" step="0.5" value="${s.multiplier}" data-wb-stage="${i}:multiplier"></label></details>`:''}<div class="node-actions"><button class="text-button" data-reference-type="class" data-reference-id="${cl.id}">职业速览</button><button data-wb-remove="${i}" ${d.stages.length===1?'disabled':''} aria-label="移除阶段${i+1}">移除</button></div>`:`<p class="path-why" tabindex="0">${esc(wbReason(c,s))}</p>${compact?'':`<button class="text-button" data-wb-character-entry="${c.id}" data-wb-route-entry="${r}" data-wb-node-entry="${i}">编辑这个节点</button>`}`}</li>`}).join('')}</ol></div>`;}
function wbStageStats(row,prev,known){const now=known?row.stats:row.gains,before=prev?(known?prev.stats:prev.gains):null;return `<div class="wb-stage-stats entry-stat-grid">${WB_KEYS.map(k=>{const v=now[k],d=before?v-before[k]:null;return `<div class="${d!==null&&d>=2.5?'gain-high':''}"><small>${statNames[k]}</small><b>${known?'':'＋'}${Number(v).toFixed(1)}</b>${d!==null&&d>0.05?`<i>+${d.toFixed(1)}</i>`:''}</div>`}).join('')}</div>`;}
function wbStageList(c,d,r){const result=wbCalculate(d);return `${!result.baselineKnown?'<p class="wb-caption">起始面板未确认，以下仅显示成长增量。</p>':''}<ol class="career-graph wb-stage-list editable-graph" aria-label="${esc(c.cn)}职业阶段">${d.stages.map((s,i)=>{const cl=wbClass(s.classId),row=result.rows[i],pets=CATALOG.petGuide.pets.filter(p=>p.compatibleClasses.includes(cl.cn)),issue=wbClassIssue(c,cl);return `<li class="career-node wb-stage ${s.phase==='third'?'wb-stage-third':''} ${issue?'wb-stage-issue':''}" id="wb-node-${i}"><div class="wb-stage-rail"><span class="wb-stage-dot">${i+1}</span></div><div class="wb-stage-card"><div class="wb-stage-top"><button class="wb-stage-icon" data-reference-type="class" data-reference-id="${cl.id}" aria-label="${esc(cl.cn)}职业速览">${classIcon(cl,44)}</button><div class="wb-stage-controls"><label class="wb-stage-class"><span>职业</span><select data-wb-stage="${i}:classId" aria-label="阶段${i+1}职业">${wbOptions(s.classId,c)}</select></label><label class="wb-stage-phase"><span>培养时期</span><select data-wb-stage="${i}:phase" aria-label="阶段${i+1}培养时期"><option value="early" ${s.phase==='early'?'selected':''} ${wbThirdOnlyClass(cl,c)||c.firstPart===false?'disabled':''}>融合前（第一、二部）</option><option value="third" ${s.phase==='third'?'selected':''}>第三部续养</option></select></label><label class="wb-stage-level"><span>等级</span><span class="wb-level-range"><span class="path-level">Lv.${row.start} →</span><input type="number" min="${row.start}" max="99" value="${row.end}" data-wb-stage="${i}:end" aria-label="阶段${i+1}结束等级"></span></label></div><button class="wb-stage-remove" data-wb-remove="${i}" ${d.stages.length===1?'disabled':''} aria-label="移除阶段${i+1}" title="移除此阶段"><svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" aria-hidden="true"><path d="M5 7h14M10 11v6M14 11v6M6 7l1 12h10l1-12M9 7V4h6v3"/></svg></button></div>${issue?`<p class="wb-node-issue" role="alert">${esc(issue)}</p>`:''}<div class="wb-stage-result"><small class="wb-stage-caption">Lv.${row.end} ${result.baselineKnown?'永久属性期望':'成长增量'}${i?'；小字为本阶段增加':''}</small><div data-wb-node-stats="${i}">${wbStageStats(row,result.rows[i-1],result.baselineKnown)}</div></div><details class="wb-stage-more" data-disclosure-key="wb-stage-${c.id}-${[...String(r)].map(ch=>ch.charCodeAt(0).toString(36)).join('')}-${i}"${s.reason?' open':''}><summary>选择理由${pets.length?'与坐骑修正':''}</summary><label class="path-reason"><span class="wb-visually-hidden">我的选择理由</span><textarea rows="2" maxlength="1500" data-wb-stage="${i}:reason" placeholder="${esc(wbReason(c,{...s,reason:''}))}">${esc(s.reason)}</textarea></label>${pets.length?`<div class="wb-mounts"><label>坐骑<select data-wb-stage="${i}:pet"><option value="">不计坐骑</option>${pets.map(p=>`<option value="${p.id}" ${s.pet===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><label>友好等级<select data-wb-stage="${i}:friendship">${[0,1,2,3,4,5].map(n=>`<option ${n===s.friendship?'selected':''}>${n}</option>`).join('')}</select></label><label>成长倍率<input type="number" min="0" max="2" step="0.5" value="${s.multiplier}" data-wb-stage="${i}:multiplier"></label></div>`:''}</details></div></li>`}).join('')}</ol>${d.stages.length<8?`<button class="wb-add-stage" data-wb-action="add"><svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" aria-hidden="true"><path d="M12 5v14M5 12h14"/></svg>添加阶段</button>`:''}`;}
function wbSummary(){const p=wbProjects[wbCharacter],d=p.lanes[p.activeRoute],r=wbCalculate(d),start=d.base,known=r.baselineKnown,out=known?r.stats:r.gains,last=r.rows.at(-1);return `<div class="wb-summary-head"><div><small>${esc(wbRouteName(p.activeRoute))} · 终点</small><b>Lv.${r.level} ${esc(last?.className||'')}</b></div><span class="wb-summary-kind">${known?'永久属性期望':'成长增量'}</span></div><div class="wb-summary-grid">${WB_KEYS.map(k=>{const gain=known?out[k]-(start[k]||0):out[k];return `<div><small>${statNames[k]}</small><b>${known?'':'＋'}${out[k].toFixed(1)}</b>${known?`<i>+${gain.toFixed(1)}</i>`:''}</div>`}).join('')}</div>${r.warnings.length?`<p class="wb-summary-warn">${r.warnings.length} 条资格提醒，见下方表格</p>`:''}`;}
function wbEditor(){const p=wbProject(),d=p.lanes[p.activeRoute],c=DB.characters.find(c=>c.id===p.characterId),available=wbAvailable(c.id);return `<div class="wb-hero">${wbCharacterChooser(c)}<div class="wb-hero-meta"><label class="wb-plan-name"><span class="wb-field-label">方案名称</span><input data-wb-name maxlength="60" value="${esc(p.name)}"></label><div class="wb-route-picker" role="group" aria-label="角色可用路线">${available.map(r=>`<button data-wb-route="${r}" aria-pressed="${r===p.activeRoute}" class="${r===p.activeRoute?'active':''}">${wbRouteAvatar(r)}<span>${wbRouteName(r)}${p.lanes[r]?'':'<small>添加路线</small>'}</span></button>`).join('')}</div></div></div><p class="wb-caption">${p.activeRoute==='common'?'此角色按共通／后期入队处理，不提供第一部三线培养。':esc(joinTextFor(c,p.activeRoute))+'；各线起始面板请按实际入队存档填写。'} ${available.length<4?'仅显示该角色可加入的路线。':''}</p>${c.canChangeClass===false?`<p class="wb-caption">${esc(c.plan)}</p>`:''}<div class="wb-layout"><div class="wb-main"><div class="wb-section-head"><h3>${wbRouteName(p.activeRoute)} · 职业路线</h3><div class="wb-actions wb-actions-quiet"><button data-wb-action="preset">带入推荐</button><button data-wb-action="removeRoute" ${Object.keys(p.lanes).length===1?'disabled':''}>移除本线</button></div></div><details class="wb-baseline"><summary>起始等级、面板与基础成长<small>Lv.${d.level}${d.baselineKnown?' · 面板已确认':' · 面板未确认'}</small></summary><p>${c.baseStats?'默认使用资料参考面板；各线入队等级和属性可能不同，请按实际存档修改。':'资料缺少初始面板，空缺暂用0占位；填写完整存档属性并确认后才计算绝对值。'}${!c.baseLevel?' 参考等级未收录，暂按'+d.level+'级起算，请按存档修改。':''}</p><label class="wb-inline-field">起始等级<input type="number" min="1" max="99" data-wb-level value="${d.level}"></label><h4>起始面板</h4><div class="wb-stat-inputs">${wbStatFields('base',d.base)}</div><label class="wb-check"><input type="checkbox" data-wb-baseline-known ${d.baselineKnown?'checked':''}>起始面板已填写完整，可参与绝对值融合</label><h4>基础成长率</h4><div class="wb-stat-inputs">${wbStatFields('growth',d.growth)}</div></details><div id="wb-graph">${wbStageList(c,d,p.activeRoute)}</div><label class="wb-notes">本线备注<textarea data-wb-notes maxlength="3000" rows="2" placeholder="记录本线的取舍、待核实事项…">${esc(d.notes)}</textarea></label></div><aside class="wb-side" aria-label="方案结果与操作"><div id="wb-summary" class="wb-summary" aria-live="polite">${wbSummary()}</div><div class="wb-side-actions"><button class="wb-primary" data-wb-action="save">保存并应用方案</button><div class="wb-side-row"><button data-wb-action="export">导出 JSON</button><label class="wb-file-button">导入方案<input type="file" accept=".json,application/json" data-wb-import></label></div><div class="wb-saved"><label>已保存的方案<select data-wb-saved><option value="">选择快照…</option>${wbSaves.map((s,i)=>`<option value="${i}">${esc(s.name)}</option>`).join('')}</select></label><button data-wb-action="load">读取</button></div>${wbUndoSnapshot?'<button class="wb-undo" data-wb-action="undo">撤销上次草稿替换／移除</button>':''}<div id="wb-status" role="status"></div></div></aside></div><div id="wb-result" class="wb-result" aria-live="polite">${wbResult()}</div><details class="wb-method"><summary>计算口径与限制</summary><p>永久属性期望＝起始属性＋Σ（实际升级次数×合计成长率÷100）。随机成长、考试最低面板、职业临时加成和坐骑临时面板不计入。坐骑仅按已核实的友好5修正；额外技能成长可修改基础成长率。先对融合前各线期望逐项取高，再按所选的一条第三部路线续养；第三部成长不会在多条线重复融合。阶段划分不代表等级上限，可将上级职业标记为第三部续养。期望逐项取高只作参考，不是随机最大值的数学期望；本计算器不合并技能经验。</p></details>`;}
function wbResult(){const p=wbProjects[wbCharacter],d=p.lanes[p.activeRoute],r=wbCalculate(d),fusion=wbFusion(p),f=n=>n.toFixed(1),cells=out=>WB_KEYS.map(k=>`<td>${out.baselineKnown?'':'＋'}${f((out.baselineKnown?out.stats:out.gains)[k])}</td>`).join('');return `<div class="wb-section-head"><h3>${p.activeRoute==='common'?'第三部出战成长参考':'融合前各线与第三部续养'}</h3></div><div class="wb-fusion-options">${Object.keys(p.lanes).filter(route=>route!=='common').map(route=>`<label><input type="checkbox" data-wb-fuse="${route}" ${p.selected.includes(route)?'checked':''}>计入${wbRouteName(route)}</label>`).join('')}</div><div class="table-wrap"><table class="wb-result-table"><thead><tr><th>路线／期望值</th>${WB_KEYS.map(k=>`<th>${statNames[k]}</th>`).join('')}</tr></thead><tbody>${Object.entries(p.lanes).filter(([route,lane])=>route!=='common'||lane.baselineKnown).map(([route,lane])=>{const out=wbCalculate(lane,{untilThird:true});return `<tr><th>${wbRouteName(route)} · ${route==='common'?'起始面板':'融合前'} Lv.${out.level}${out.baselineKnown?'':'（仅增量）'}</th>${cells(out)}</tr>`}).join('')}${fusion.stats&&p.activeRoute!=='common'?`<tr class="fusion-row"><th>融合参考 · Lv.${fusion.level}</th>${WB_KEYS.map(k=>`<td>${f(fusion.stats[k])}</td>`).join('')}</tr>`:''}${fusion.continuation?`<tr class="fusion-row"><th>第三部续养 · Lv.${fusion.continuation.level}${fusion.continuation.baselineKnown?'':'（仅增量）'}</th>${cells(fusion.continuation)}</tr>`:''}</tbody></table></div>${Object.keys(p.lanes).length>1?`<label>第三部接续路线<select data-wb-continuation>${Object.keys(p.lanes).map(route=>`<option value="${route}" ${route===fusion.continuationRoute?'selected':''}>${wbRouteName(route)}</option>`).join('')}</select></label>`:''}<p class="wb-caption">${p.activeRoute==='common'?'本角色不参与跨线融合，仅估算第三部出战升级；起始面板未确认时只显示成长增量。':'融合前成果逐项取高；第三部仅接续所选一条路线。'}${fusion.excluded.length?' '+fusion.excluded.map(wbRouteName).join('、')+'起始面板未确认，未计入绝对值融合。':''}${!fusion.stats&&p.activeRoute!=='common'?' 请勾选路线并确认完整起始面板。':''}</p><details><summary>本线职业资格提醒（${r.warnings.length}）</summary>${r.warnings.length?`<ul>${r.warnings.map(w=>`<li>${esc(w)}</li>`).join('')}</ul>`:'<p>仍需核对技能资格、解锁条件与职业熟练。</p>'}</details>`;}
function calculatorPage(){return `<div class="page-title"><h1>自定义养成</h1><p>为同一角色编辑各线职业路径，比较永久属性并查看融合参考。</p></div><section id="custom-workbench" class="custom-workbench"><div id="wb-editor">${wbEditor()}</div></section>`;}
pages.calculator='自定义养成';
function wbCharacterPlan(c,r){const p=wbProjects[c.id];try{if(p&&(!wbAvailable(c.id).includes(r)||p.lanes[r])){const project=wbProjectValidate(p),key=project.lanes[r]?r:project.activeRoute;return {draft:project.lanes[key],r:key,custom:true};}}catch{}const allowed=wbAvailable(c.id),key=allowed.includes(r)?r:allowed[0];return {draft:wbPreset(c.id,key),r:key,custom:false};}
careerDiagram=function(c){const plan=wbCharacterPlan(c,routeContext(c));return cultivationDecisionPanel(c)+`<div class="wb-path-heading"><b>${wbRouteName(plan.r)} · ${plan.custom?'我的路线':'推荐路线示例'}</b><button data-wb-character-entry="${c.id}" data-wb-route-entry="${plan.r}">编辑养成路线</button></div>`+wbGraph(c,plan.draft,{r:plan.r,alternatives:!plan.custom})+'<p class="wb-caption">图中为资料面板推算的永久属性期望，等级安排可自定义；职业悬停查看资格与成长。</p>'+careerAlternativesPanel(c);};
cardCareer=function(c){const plan=wbCharacterPlan(c,routeContext(c));return `<div class="card-career-modern"><div class="card-career-label"><span>${plan.custom?'我的职业路线':'职业路线示例'}</span><button class="text-button" data-wb-character-entry="${c.id}" data-wb-route-entry="${plan.r}">编辑</button></div>${wbGraph(c,plan.draft,{compact:true,r:plan.r,alternatives:!plan.custom})}</div>`;};
function wbUpdate(editor=false,graph=false){const p=wbProjects[wbCharacter];p.lanes[p.activeRoute]=wbValidate(wbDraft);wbDraft=p.lanes[p.activeRoute];wbPersist();const el=$('#wb-editor');if(!el)return;if(editor){el.innerHTML=viewHTML(wbEditor());return;}if(graph){const target=$('#wb-graph'),focus=document.activeElement?.getAttribute('data-wb-stage');target.innerHTML=viewHTML(wbStageList(DB.characters.find(c=>c.id===wbCharacter),wbDraft,p.activeRoute));if(focus)Array.from(target.querySelectorAll('[data-wb-stage]')).find(n=>n.getAttribute('data-wb-stage')===focus)?.focus({preventScroll:true});}else{const calc=wbCalculate(wbDraft);calc.rows.forEach((row,i)=>{const n=document.querySelector(`[data-wb-node-stats="${i}"]`);if(n)n.innerHTML=wbStageStats(row,calc.rows[i-1],calc.baselineKnown);const node=document.querySelector('#wb-node-'+i);if(node){const level=node.querySelector('.path-level');if(level)level.textContent='Lv.'+row.start+' →';const caption=node.querySelector('.wb-stage-caption');if(caption)caption.textContent='Lv.'+row.end+(calc.baselineKnown?' 永久属性期望':' 成长增量')+(i?'；小字为本阶段增加':'');const end=node.querySelector('[data-wb-stage$=":end"]');if(end){end.min=row.start;if(end!==document.activeElement)end.value=row.end;}}});}const summary=$('#wb-summary');if(summary)summary.innerHTML=viewHTML(wbSummary());$('#wb-result').innerHTML=viewHTML(wbResult());}
function wbStatus(text){const n=document.querySelector('#wb-status');if(n)n.textContent=text;}
function wbOpen(id,r,node){const p=wbProject(id);if(wbAvailable(id).includes(r)){p.activeRoute=r;p.lanes[r]||=wbPreset(id,r);if(!p.selected.includes(r))p.selected.push(r);}wbDraft=p.lanes[p.activeRoute];wbPersist();$('#detail').close();location.hash='calculator';render();if(node!==undefined)document.querySelector('#wb-node-'+node)?.scrollIntoView({block:'nearest',inline:'center'});}
document.addEventListener('input',e=>{const t=e.target;if(!t.closest('#wb-editor'))return;const p=wbProjects[wbCharacter],d=p.lanes[p.activeRoute];wbDraft=d;if(t.dataset.wbStat){const [kind,key]=t.dataset.wbStat.split(':');d[kind][key]=wbNumber(t.value,0,kind==='growth'?300:999);}else if(t.hasAttribute('data-wb-name'))p.name=t.value;else if(t.hasAttribute('data-wb-notes'))d.notes=t.value;else if(t.hasAttribute('data-wb-level')){if(t.value==='')return;d.level=Math.floor(wbNumber(t.value,1,99));}else if(t.dataset.wbStage){const [i,key]=t.dataset.wbStage.split(':');if(t.tagName==='SELECT')return;if(key==='end'){if(t.value==='')return;const row=wbCalculate(d).rows[Number(i)];d.stages[Number(i)].levels=Math.floor(wbNumber(t.value,row.start,99))-row.start;}else d.stages[Number(i)][key]=key==='reason'?t.value:wbNumber(t.value);}else return;wbUpdate();});
document.addEventListener('change',async e=>{const t=e.target;if(t.hasAttribute('data-wb-character')){wbProject(t.value);wbUpdate(true);}else if(t.hasAttribute('data-wb-fuse')){const p=wbProjects[wbCharacter],r=t.dataset.wbFuse;p.selected=p.selected.filter(x=>x!==r);if(t.checked)p.selected.push(r);wbDraft=p.lanes[p.activeRoute];wbUpdate();}else if(t.hasAttribute('data-wb-baseline-known')){wbDraft.baselineKnown=t.checked;wbUpdate(false,true);}else if(t.hasAttribute('data-wb-continuation')){wbProjects[wbCharacter].continuationRoute=t.value;wbUpdate();}else if(t.hasAttribute('data-wb-level')){wbDraft.level=Math.floor(wbNumber(t.value,1,99));wbUpdate(false,true);}else if(t.dataset.wbStage){const [i,key]=t.dataset.wbStage.split(':');if(key==='end'){const rows=wbCalculate(wbDraft).rows;wbDraft.stages[Number(i)].levels=Math.floor(wbNumber(t.value,rows[Number(i)].start,99))-rows[Number(i)].start;t.value=rows[Number(i)].start+wbDraft.stages[Number(i)].levels;wbUpdate();}else if(t.tagName==='SELECT'){const s=wbDraft.stages[Number(i)];s[key]=key==='friendship'?Number(t.value):t.value;if(key==='classId')s.pet='';if(key==='phase'){wbDraft.stages.forEach((stage,at)=>{stage.phase=at<Number(i)?(t.value==='early'?'early':stage.phase):t.value;});}wbUpdate(false,true);}}else if(t.hasAttribute('data-wb-import')){try{const f=t.files?.[0];if(!f)return;if(f.size>262144)throw Error('方案文件需小于256KB');const p=wbMigrate(JSON.parse(await f.text()));wbProjects[p.characterId]=p;wbProject(p.characterId);wbUpdate(true);wbStatus('方案已导入并保存在当前浏览器。');}catch(err){wbStatus('导入失败：'+err.message);}}});
document.addEventListener('click',e=>{const entry=e.target.closest('[data-wb-character-entry]');if(entry){e.preventDefault();e.stopPropagation();wbOpen(entry.dataset.wbCharacterEntry,entry.dataset.wbRouteEntry,entry.dataset.wbNodeEntry);return;}const routeButton=e.target.closest('[data-wb-route]');if(routeButton){const p=wbProject(),r=routeButton.dataset.wbRoute;if(!wbAvailable(p.characterId).includes(r))return;p.lanes[r]||=wbPreset(p.characterId,r);p.activeRoute=r;if(!p.selected.includes(r))p.selected.push(r);wbDraft=p.lanes[r];wbUpdate(true);return;}const remove=e.target.closest('[data-wb-remove]');if(remove){if(wbDraft.stages.length>1)wbDraft.stages.splice(Number(remove.dataset.wbRemove),1);wbUpdate(false,true);return;}const b=e.target.closest('[data-wb-action]');if(!b)return;const action=b.dataset.wbAction,p=wbProject(),d=p.lanes[p.activeRoute];wbDraft=d;if(action==='preset'){wbRemember(p);wbDraft=wbPreset(d.characterId,p.activeRoute);wbUpdate(true);}if(action==='add'){if(d.stages.length<8)d.stages.push({...d.stages.at(-1),levels:0,reason:''});wbUpdate(false,true);}if(action==='removeRoute'&&Object.keys(p.lanes).length>1){wbRemember(p);delete p.lanes[p.activeRoute];p.selected=p.selected.filter(r=>p.lanes[r]);p.activeRoute=Object.keys(p.lanes)[0];wbDraft=p.lanes[p.activeRoute];wbUpdate(true);}if(action==='undo'&&wbUndoSnapshot){const restored=wbProjectValidate(wbUndoSnapshot);wbUndoSnapshot=null;wbProjects[restored.characterId]=restored;wbProject(restored.characterId);wbUpdate(true);wbStatus('已恢复上次操作前的草稿。');}if(action==='save'){const saved=wbSaveApply(p);$('#wb-editor').innerHTML=viewHTML(wbEditor());wbStatus(saved?'已保存并应用方案到当前浏览器。':(wbLastError||'浏览器无法保存，请导出方案文件。'));}if(action==='load'){const index=document.querySelector('[data-wb-saved]').value;if(index===''){wbStatus('请先选择已保存方案。');return;}try{const saved=wbMigrate(wbSaves[Number(index)]);wbProjects[saved.characterId]=saved;wbProject(saved.characterId);wbUpdate(true);wbStatus('方案已读入草稿；尚未应用到攻略。');}catch(err){wbStatus('读取失败：'+err.message);}}if(action==='export'){const url=URL.createObjectURL(new Blob([JSON.stringify(p,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='多路线养成方案.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}});
// Prevent the enclosing character card from opening its dossier for editor links.
document.addEventListener('click',e=>{const entry=e.target.closest('[data-wb-character-entry]');if(entry){e.preventDefault();e.stopImmediatePropagation();wbOpen(entry.dataset.wbCharacterEntry,entry.dataset.wbRouteEntry,entry.dataset.wbNodeEntry);}},true);

// One non-modal career preview, shared by cards, paths, and calculator choices.
let classHover=null,classHoverTrigger=null,classHoverTimer=null,classHoverSuppress=false,classHoverPinned=false;
function classQuickHTML(cl){return `<div class="class-quick-head">${classIcon(cl,40)}<div><b>${esc(cl.cn)}</b><small>${esc(cl.col_1)} · 移动${esc(cl.col_34||'—')}</small></div><button data-class-quick-close aria-label="关闭职业速览"><svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="m6 6 12 12M18 6 6 18"/></svg></button></div><p>${esc(requirement(cl))}</p><div class="quick-growth">${WB_KEYS.map(k=>`<span>${statNames[k]} <b>${Number(cl.growth[k])>0?'+':''}${cl.growth[k]}%</b></span>`).join('')}</div><p><b>可用：</b>${esc(cl.allowedSkills.join(' / ')||'未记录')}</p><p><b>熟练：</b>${esc(cl.col_37)} · ${esc(CATALOG.masterySkills[cl.col_37]?.description||'效果未收录')}</p>${cl.unlock?`<p class="muted">${esc(cl.unlock)}</p>`:''}<button class="text-button" data-class-full="${cl.id}">完整资料与成长预览 ↗</button>`;}
function closeClassQuick(returnFocus=false){clearTimeout(classHoverTimer);if(classHoverTrigger){classHoverTrigger.setAttribute('aria-expanded','false');classHoverTrigger.removeAttribute('aria-describedby');}const trigger=classHoverTrigger;classHover?.remove();classHover=null;classHoverTrigger=null;classHoverPinned=false;if(returnFocus&&trigger?.isConnected){classHoverSuppress=true;trigger.focus();setTimeout(()=>classHoverSuppress=false,80);}}
function positionClassQuick(){if(!classHover||!classHoverTrigger?.isConnected){closeClassQuick();return;}const r=classHoverTrigger.getBoundingClientRect(),p=classHover.getBoundingClientRect(),w=document.documentElement.clientWidth,h=window.innerHeight;const left=Math.max(8,Math.min(r.left,w-p.width-8)),top=r.bottom+p.height+8<h?r.bottom+6:Math.max(8,r.top-p.height-6);classHover.style.left=left+'px';classHover.style.top=top+'px';}
function openClassQuick(trigger){clearTimeout(classHoverTimer);const cl=wbClass(trigger.dataset.referenceId);if(!cl)return;if(classHoverTrigger===trigger&&classHover)return;closeClassQuick();classHoverTrigger=trigger;classHover=document.createElement('section');classHover.id='class-quick-preview';classHover.className='class-quick-preview';classHover.setAttribute('role','region');classHover.setAttribute('aria-label',cl.cn+'职业速览');classHover.innerHTML=classQuickHTML(cl);(document.querySelector('#sourceDialog[open]')||document.querySelector('#detail[open]')||document.body).appendChild(classHover);trigger.removeAttribute('title');trigger.setAttribute('aria-expanded','true');trigger.setAttribute('aria-describedby',classHover.id);positionClassQuick();}
function classQuickTrigger(t){return t.closest?.('[data-reference-type="class"]');}
document.addEventListener('pointerover',e=>{const t=classQuickTrigger(e.target);if(t&&e.pointerType!=='touch'){clearTimeout(classHoverTimer);classHoverTimer=setTimeout(()=>openClassQuick(t),130);}if(classHover?.contains(e.target))clearTimeout(classHoverTimer);});
document.addEventListener('pointerout',e=>{if(classHoverPinned)return;if(classQuickTrigger(e.target)||classHover?.contains(e.target)){if(e.relatedTarget&&(classHover?.contains(e.relatedTarget)||classHoverTrigger?.contains(e.relatedTarget)))return;clearTimeout(classHoverTimer);classHoverTimer=setTimeout(()=>closeClassQuick(),180);}});
document.addEventListener('focusin',e=>{if(classHoverSuppress)return;const t=classQuickTrigger(e.target);if(t)openClassQuick(t);else if(classHover&&!classHover.contains(e.target))closeClassQuick();});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&classHover){e.preventDefault();e.stopImmediatePropagation();closeClassQuick(true);}},true);
document.addEventListener('click',e=>{const full=e.target.closest('[data-class-full]');if(full){const id=full.dataset.classFull;closeClassQuick();openReferenceDialog('class',id);e.stopImmediatePropagation();return;}if(e.target.closest('[data-class-quick-close]')){closeClassQuick(true);e.stopImmediatePropagation();return;}const t=classQuickTrigger(e.target);if(t){e.preventDefault();e.stopImmediatePropagation();if(classHoverTrigger===t&&classHover&&classHoverPinned&&e.detail!==0)closeClassQuick();else{openClassQuick(t);classHoverPinned=true;if(e.detail===0)classHover.querySelector('[data-class-full]')?.focus();}return;}if(classHover&&!classHover.contains(e.target))closeClassQuick();},true);
window.addEventListener('resize',positionClassQuick);document.addEventListener('scroll',e=>{if(!classHover?.contains(e.target))closeClassQuick();},true);
document.addEventListener('close',e=>{if(classHover&&e.target.contains(classHover))closeClassQuick();},true);
const quickRender=render;render=function(){closeClassQuick();return quickRender();};

// Retain the full rationale behind disclosure; the main route stays compact.
const fullStageOption=stageClass;
stageClass=function(name,label,c,context={}){const html=fullStageOption(name,label,c,context),cl=classBy(name);if(!cl)return html;const headEnd=html.indexOf('</div>')+6,pillsEnd=html.indexOf('</div>',headEnd)+6;if(headEnd<6||pillsEnd<6)return html;const head=html.slice(0,pillsEnd).replace('<b>'+cl.cn+'</b>',`<button class="text-button stage-class-name" data-reference-type="class" data-reference-id="${cl.id}">${esc(cl.cn)}</button>`);return head+'<details class="class-basics"><summary>培养理由与成长细节</summary>'+html.slice(pillsEnd,-6)+'</details></div>';};
